-- Dating proposals and personal safety planning. No precise live location is shared automatically.
-- Reuses the existing date_proposals table created by the growth engine. Legacy columns remain compatible.
alter table public.date_proposals add column if not exists venue_name text;
alter table public.date_proposals add column if not exists venue_address text;
comment on column public.date_proposals.venue_address is 'User-entered meeting-place text. This is not live GPS tracking and is visible only to the Match participants.';

create table if not exists public.date_safety_plans(
  proposal_id uuid not null references public.date_proposals(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,public_place_confirmed boolean not null default false,transport_home_planned boolean not null default false,checkin_at timestamptz,notes text check(notes is null or char_length(notes)<=500),updated_at timestamptz not null default now(),primary key(proposal_id,user_id)
);
alter table public.date_safety_plans enable row level security;
drop policy if exists date_safety_plans_self_read on public.date_safety_plans;create policy date_safety_plans_self_read on public.date_safety_plans for select to authenticated using(user_id=auth.uid());
revoke insert,update,delete on public.date_safety_plans from authenticated,anon;grant select on public.date_safety_plans to authenticated;

create or replace function public.create_date_proposal(p_match uuid,p_venue_name text,p_venue_address text,p_proposed_at timestamptz) returns uuid language plpgsql security definer set search_path=public as $$declare u uuid:=auth.uid();m public.matches%rowtype;r uuid;begin if u is null then raise exception'not_authenticated';end if;select*into m from public.matches where id=p_match and status='active' and(u=user_a or u=user_b);if not found then raise exception'active_match_required';end if;if p_proposed_at<=now()+interval'30 minutes'or p_proposed_at>now()+interval'90 days'then raise exception'invalid_time';end if;if char_length(trim(p_venue_name))not between 2 and 120 or char_length(trim(p_venue_address))not between 2 and 220 then raise exception'invalid_venue';end if;insert into public.date_proposals(match_id,proposed_by,activity_type,area_label,venue_name,venue_address,proposed_at,status)values(p_match,u,'in_person_date',trim(p_venue_name),trim(p_venue_name),trim(p_venue_address),p_proposed_at,'proposed')returning id into r;return r;end;$$;
create or replace function public.respond_date_proposal(p_proposal uuid,p_response text) returns jsonb language plpgsql security definer set search_path=public as $$declare u uuid:=auth.uid();d public.date_proposals%rowtype;m public.matches%rowtype;begin if u is null then raise exception'not_authenticated';end if;if p_response not in('accepted','declined','cancelled')then raise exception'invalid_response';end if;select*into d from public.date_proposals where id=p_proposal for update;if not found then raise exception'proposal_unavailable';end if;select*into m from public.matches where id=d.match_id and status='active'and(u=user_a or u=user_b);if not found then raise exception'active_match_required';end if;if p_response='cancelled'and d.proposed_by<>u then raise exception'forbidden';end if;if p_response in('accepted','declined')and d.proposed_by=u then raise exception'forbidden';end if;update public.date_proposals set status=p_response,updated_at=now() where id=p_proposal;return jsonb_build_object('ok',true,'status',p_response);end;$$;
create or replace function public.get_my_date_proposals() returns table(proposal_id uuid,match_id uuid,other_user_id uuid,other_name text,venue_name text,venue_address text,proposed_at timestamptz,status text,is_proposer boolean) language plpgsql security definer stable set search_path=public as $$declare u uuid:=auth.uid();begin if u is null then raise exception'not_authenticated';end if;return query select d.id,d.match_id,case when m.user_a=u then m.user_b else m.user_a end,p.display_name,coalesce(d.venue_name,d.area_label,d.activity_type),coalesce(d.venue_address,d.area_label,''),d.proposed_at,d.status,d.proposed_by=u from public.date_proposals d join public.matches m on m.id=d.match_id and m.status='active' join public.profiles p on p.id=case when m.user_a=u then m.user_b else m.user_a end where u in(m.user_a,m.user_b) order by d.proposed_at desc nulls last,d.created_at desc limit 100;end;$$;
create or replace function public.save_date_safety_plan(p_proposal uuid,p_public boolean,p_transport boolean,p_checkin timestamptz,p_notes text) returns jsonb language plpgsql security definer set search_path=public as $$declare u uuid:=auth.uid();begin if u is null then raise exception'not_authenticated';end if;if not exists(select 1 from public.date_proposals d join public.matches m on m.id=d.match_id where d.id=p_proposal and m.status='active' and u in(m.user_a,m.user_b))then raise exception'forbidden';end if;if p_checkin is not null and(p_checkin<now()or p_checkin>now()+interval'90 days')then raise exception'invalid_checkin';end if;if char_length(coalesce(p_notes,''))>500 then raise exception'notes_too_long';end if;insert into public.date_safety_plans(proposal_id,user_id,public_place_confirmed,transport_home_planned,checkin_at,notes)values(p_proposal,u,p_public,p_transport,p_checkin,nullif(trim(p_notes),''))on conflict(proposal_id,user_id)do update set public_place_confirmed=excluded.public_place_confirmed,transport_home_planned=excluded.transport_home_planned,checkin_at=excluded.checkin_at,notes=excluded.notes,updated_at=now();return jsonb_build_object('ok',true);end;$$;
revoke all on function public.create_date_proposal(uuid,text,text,timestamptz),public.respond_date_proposal(uuid,text),public.get_my_date_proposals(),public.save_date_safety_plan(uuid,boolean,boolean,timestamptz,text) from public,anon;
grant execute on function public.create_date_proposal(uuid,text,text,timestamptz),public.respond_date_proposal(uuid,text),public.get_my_date_proposals(),public.save_date_safety_plan(uuid,boolean,boolean,timestamptz,text) to authenticated;
